    "content": "新华社天津11月18日电（记者徐思钰）记者18日从天津市生态环境局获悉，《天津市重污染天气应对预案》日前印发实施，新预案标志着天津重污染天气治理理念由过去的被动“应急”处置转向全过程系统“应对”，旨在进一步巩固空气质量改善成果，统筹环境保护与经济社会发展。 近年来，天津大气污染治理成效显著。2026年1月至10月，天津PM2.5平均浓度为34.4微克/立方米，优良天数比例达69.4%，未出现重污染天气。但受秋冬季静稳、高湿、逆温等不利气象条件及区域传输影响，重污染风险依然存在。为此，天津着眼全过程系统应对重污染天气…"
