    "description": "新华社法兰克福11月18日电（记者刘向 单玮怡）欧洲央行18日发布金融稳定评估报告说，人工智能企业估值、财政失衡以及地缘经济紧张局势带来的风险，正在影响欧元区金融稳定前景。 欧洲央行当天发布的新闻公报指出，对人工智能企业盈利预期的过度乐观，使金融市场容易受到估值突然调整的冲击。此外，主要发达经济体财政失衡也可能导致全球主权债务风险重新定价。 欧洲央行副行长鲍里斯·武伊契奇在新闻公报中指出，地缘经济不确定性持续存在，以及金融体系对人工智能…",
    "content": "新华社法兰克福11月18日电（记者刘向 单玮怡）欧洲央行18日发布金融稳定评估报告说，人工智能企业估值、财政失衡以及地缘经济紧张局势带来的风险，正在影响欧元区金融稳定前景。 欧洲央行当天发布的新闻公报指出，对人工智能企业盈利预期的过度乐观，使金融市场容易受到估值突然调整的冲击。此外，主要发达经济体财政失衡也可能导致全球主权债务风险重新定价。 欧洲央行副行长鲍里斯·武伊契奇在新闻公报中指出，地缘经济不确定性持续存在，以及金融体系对人工智能相关领域的风险敞口扩大，欧元区金融稳定面临的风险仍处于较高水平。银行业具备较强的…"
