    "content": "（深圳综合讯）中国国家主席习近平与韩国总统李在明举行会谈时，提出“循序渐进开展健康有益的文化交流”。中国也承诺在电影和游戏等领域给予韩国“最惠国待遇”， 长达10年的“限韩令”或迎来实质性松绑 。 综合新华社和韩联社报道，以亚太经合组织（APEC）峰会为契机，习近平和李在明星期三（11月18日）在深圳举行一年多来的第三次面对面会谈。 习近平说，中韩实质性完成了自贸协定（FTA）第二阶段谈判，双方要用好用足这一制度性安排，加强宏观政策协调，培育人工智能等新兴科技产业合作生态，共享发展机遇。“中方愿同韩方一道，持续促进…"
