    "description": "巴基斯坦三军新闻局18日发表声明说，巴陆军当天成功试射“法塔赫－3”超音速巡航导弹。 声明说，“法塔赫－3”超音速巡航导弹配备了先进的导航和推进系统，能对远距离目标实施高精度、高杀伤力打击，将显著提升巴陆军火箭部队的作战灵活性和打击范围。 声明还说，巴基斯坦总统扎尔达里、总理夏巴兹、陆军参谋长穆尼尔祝贺导弹成功试射。",
    "content": "巴基斯坦三军新闻局18日发表声明说，巴陆军当天成功试射“法塔赫－3”超音速巡航导弹。 声明说，“法塔赫－3”超音速巡航导弹配备了先进的导航和推进系统，能对远距离目标实施高精度、高杀伤力打击，将显著提升巴陆军火箭部队的作战灵活性和打击范围。 声明还说，巴基斯坦总统扎尔达里、总理夏巴兹、陆军参谋长穆尼尔祝贺导弹成功试射。"
