    "content": "美国当地时间11月17日，华特迪士尼公司（迪士尼，The Walt Disney Company，NYSE：DIS）发布截至2026年10月3日的2026财年第四季度及全年业绩。 财务数据显示，第四季度迪士尼总收入约259.47亿美元，同比增长约15.5%；归母净利润约26.12亿美元，同比增长约98.93%。全年来看，迪士尼2026财年的全年收入约1023.44亿美元，同比增长约8.39%，为该公司年度收入首次超过1000亿美元；归母净利润约98.99亿美元，同比减少约20.2%。 澎湃新闻（www.thepap…"
