    "content": "新华社开罗11月18日电（记者徐皓夫 董修竹）“面具之韵·文明对话”文化交流活动17日在开罗中国文化中心举行，向埃及民众展示贵州传统戏剧文化及其历史底蕴。 本次活动由贵州广播电视台和开罗中国文化中心联合主办，是2026年“中非人文交流年”系列活动之一。 埃及外交部前副部长、埃及中国友好协会副会长阿里·希夫尼在致辞中说，埃及和中国同为文明古国，文化交流是深厚历史关系的自然延伸。此次活动有助于展示中国的文化艺术和多元的人文风貌，搭建中国各地与埃及加强沟通的桥梁，对深化文化交流富有启示意义。 中国驻埃及大使馆参赞兼开罗中…"
