    "description": "新华社土耳其安塔利亚11月18日电（记者王腾飞）据土耳其媒体报道，一架俄罗斯客机18日在收到炸弹威胁后，降落在土耳其南部的安塔利亚机场。 报道说，该客机载有65名乘客和4名机组人员，飞机降落后被引导至安全区域，机上所有人员已全部撤离，安全人员随后开始对飞机进行搜查。",
    "content": "新华社土耳其安塔利亚11月18日电（记者王腾飞）据土耳其媒体报道，一架俄罗斯客机18日在收到炸弹威胁后，降落在土耳其南部的安塔利亚机场。 报道说，该客机载有65名乘客和4名机组人员，飞机降落后被引导至安全区域，机上所有人员已全部撤离，安全人员随后开始对飞机进行搜查。"
