    "description": "新华社伦敦11月18日电（记者高文成）英国海上贸易行动办公室18日发布通报说，一艘油轮17日在霍尔木兹海峡遭不明发射物击中并起火，一名海员失踪，搜救工作正在进行。 通报说，事发地点位于阿曼海塞卜以北约13海里（约24公里）处。油轮遭袭后发生火灾，目前大火已被扑灭。一名海员下落不明，船舶受损情况及事件对环境的影响尚不清楚。 英国海上贸易行动办公室此前通报说，另一艘油轮16日在霍尔木兹海峡接连遭到两次袭击，这种同一艘船舶连续遇袭的情况在该机…",
    "content": "新华社伦敦11月18日电（记者高文成）英国海上贸易行动办公室18日发布通报说，一艘油轮17日在霍尔木兹海峡遭不明发射物击中并起火，一名海员失踪，搜救工作正在进行。 通报说，事发地点位于阿曼海塞卜以北约13海里（约24公里）处。油轮遭袭后发生火灾，目前大火已被扑灭。一名海员下落不明，船舶受损情况及事件对环境的影响尚不清楚。 英国海上贸易行动办公室此前通报说，另一艘油轮16日在霍尔木兹海峡接连遭到两次袭击，这种同一艘船舶连续遇袭的情况在该机构的通报中较为少见。该船在海塞卜以北约7海里（约13公里）处首次遭袭后失去动力、…"
