    "content": "新华社哈尔滨11月18日电（记者沈易瑾）记者18日从由中共黑龙江省委宣传部、黑龙江省人民政府新闻办公室主办的“开局起步‘十五五’——奋力谱写中国式现代化黑龙江新篇章”系列主题新闻发布会获悉，黑龙江省今年以来调整优化1600多个学科专业点。新增学科专业中，85%服务龙江现代化产业体系，推动高校人才培养与产业需求进一步衔接。 黑龙江省教育厅副厅长赵雅琴介绍，今年年初，黑龙江出台学科专业设置调整优化实施方案，围绕国家“十五五”规划纲要部署，以及黑龙江省重点发展的12个千亿级特色产业集群、5个百亿级新兴产业集群，梳理形成产…"
