    "title": "财经深一度丨金融“活水”赋能制造业产业升级",
    "link": "http://www.news.cn/20261118/03d7e01c5ee24a819ba976a37fe35ed0/c.html",
    "pub_date": "2026-11-18 21:12:52",
    "author": "",
    "description": "新华社北京11月18日电 题：金融“活水”赋能制造业产业升级 新华社记者吴雨 制造业是立国之本、强国之基。今年以来，银行业持续优化金融供给，依托产业集群开展批量授信，打造全周期陪伴式服务，推动金融资源加速向先进制造业集聚，为制造业转型升级注入强劲动能。 宁庆空天智能装备（南京）股份有限公司车间内，大飞机配套零部件正加紧生产。订单集中落地时，企业流动资金一度承压。近期中国建设银行依托集群授信模式，为企业发放1000万元贷款，5个工作日内完…",
    "content": "新华社北京11月18日电 题：金融“活水”赋能制造业产业升级 新华社记者吴雨 制造业是立国之本、强国之基。今年以来，银行业持续优化金融供给，依托产业集群开展批量授信，打造全周期陪伴式服务，推动金融资源加速向先进制造业集聚，为制造业转型升级注入强劲动能。 宁庆空天智能装备（南京）股份有限公司车间内，大飞机配套零部件正加紧生产。订单集中落地时，企业流动资金一度承压。近期中国建设银行依托集群授信模式，为企业发放1000万元贷款，5个工作日内完成审批放款，及时保障了企业原材料备货与订单交付。 高效支持的背后是建行针对制造业…"
