    "description": "新华社济南11月18日电 据济南市纪委监委11月18日通报，经济南市委批准，济南市纪委监委对济南市历下区政协原党组书记、主席王勇严重违纪违法问题进行了立案审查调查。 经查，王勇违背组织原则，违规为他人在职级晋升中谋取利益；廉洁底线失守，违规收受可能影响公正执行公务的消费卡；违规干预和插手司法活动；贪欲膨胀，以权谋私，利用职务便利为他人在项目承揽、资金拨付等方面谋取利益，并非法收受巨额财物。 王勇严重违反党的组织纪律、廉洁纪律和工作纪律，…",
    "content": "新华社济南11月18日电 据济南市纪委监委11月18日通报，经济南市委批准，济南市纪委监委对济南市历下区政协原党组书记、主席王勇严重违纪违法问题进行了立案审查调查。 经查，王勇违背组织原则，违规为他人在职级晋升中谋取利益；廉洁底线失守，违规收受可能影响公正执行公务的消费卡；违规干预和插手司法活动；贪欲膨胀，以权谋私，利用职务便利为他人在项目承揽、资金拨付等方面谋取利益，并非法收受巨额财物。 王勇严重违反党的组织纪律、廉洁纪律和工作纪律，构成严重职务违法并涉嫌受贿犯罪，且在党的十八大后不收敛、不收手，性质严重，影响恶…"
