    "author": "",
    "description": "新华社东京11月18日电（记者李子越 杨智翔）日本多个民间团体18日共同向日本外务省提交诉求书，要求政府坚持“无核三原则”。 “无核三原则”指“不拥有、不制造、不运进核武器”。现行“安保三文件”中的日本《国家安全保障战略》明确表示，坚持“无核三原则”的基本方针“今后不会改变”。但据日本媒体近期报道，日本政府正考虑在计划于年底修订的《国家安全保障战略》中写入“无核三原则”例外情况，或允许在紧急情况下将核武器运进日本。 针对这一动向，日本民…",
    "content": "新华社东京11月18日电（记者李子越 杨智翔）日本多个民间团体18日共同向日本外务省提交诉求书，要求政府坚持“无核三原则”。 “无核三原则”指“不拥有、不制造、不运进核武器”。现行“安保三文件”中的日本《国家安全保障战略》明确表示，坚持“无核三原则”的基本方针“今后不会改变”。但据日本媒体近期报道，日本政府正考虑在计划于年底修订的《国家安全保障战略》中写入“无核三原则”例外情况，或允许在紧急情况下将核武器运进日本。 针对这一动向，日本民间团体在18日提交的诉求书中指出，“无核三原则”是日本长期奉行的国家方针，具有极…"
