    "content": "11月18日，深圳的外交日程格外密集。 凌晨，参加亚太经合组织（APEC）第三十三次领导人非正式会议的各经济体领导人陆续抵达。上午，APEC工商领导人峰会在深圳前海国际会议中心举行开幕式，国家主席习近平发表主旨演讲。 与此同时，中国的双边及多边外交也密集展开：继17日会见六个经济体领导人后，习近平主席18日上午会见韩国总统李在明，中午时分会见俄罗斯总统普京。下午，美国总统特朗普抵达深圳，习近平亲自前往机场迎接。当晚，深圳还迎来APEC领导人会议周的欢迎宴会。 从区域经济合作到双边外交，再到即将举行的中俄美元首首次三…"
