    "content": "新华社深圳11月18日电 2026年亚太经合组织工商领导人峰会深圳倡议 共促繁荣、共赢未来 2026年11月17日至18日，亚太工商界领袖相聚中国深圳，出席亚太经合组织（APEC）工商领导人峰会（以下简称工商峰会），围绕“共促繁荣、共赢未来”的峰会主题，深入探讨亚太区域开放合作、繁荣发展大计。 结合工商峰会的广泛讨论与APEC工商咨询理事会（ABAC）今年取得的丰硕成果，特发起本项倡议，凝聚亚太工商界的共同心声与期盼：我们呼吁各方携手构建开放包容、创新增长、互联互通、合作共赢的亚太共同体，并决心参与推动亚太共同体建…"
