    "description": "11月18日至19日，亚太经合组织（APEC）第三十三次领导人非正式会议在深圳举行。“可持续市场倡议”总裁、全球特使塞菲看好中国经济前景，她认为中国的发展蕴藏巨大机遇，提振了亚太和全球市场信心。 策划：詹勇 刘加文 执行策划：刘洪 统筹：汤丹鹭 记者：王小玉 文字：任钰 高姗姗 刘菲 视频制作：王琎 视觉设计：姜子涵 新华网海外社交媒体传播中心制作 （新华网原创新闻作品）",
    "content": "11月18日至19日，亚太经合组织（APEC）第三十三次领导人非正式会议在深圳举行。“可持续市场倡议”总裁、全球特使塞菲看好中国经济前景，她认为中国的发展蕴藏巨大机遇，提振了亚太和全球市场信心。 策划：詹勇 刘加文 执行策划：刘洪 统筹：汤丹鹭 记者：王小玉 文字：任钰 高姗姗 刘菲 视频制作：王琎 视觉设计：姜子涵 新华网海外社交媒体传播中心制作 （新华网原创新闻作品）"
