    "content": "Anthropic PBC即将为可能成为史上规模最大的首次公开募股(IPO)定价，尽管科技股已连续多日震荡，可能给这家初创公司期待已久的上市带来压力。周二有报道称，这家AI模型开发商正引导潜在IPO投资者，预计将发行价定在价格区间上端或更高水平。据知情人士透露，需求正在升温，承销银行称，此次IPO接近七倍超额认购。根据申报文件，Anthropic及其七名联合创始人合计计划发行8.25亿股，每股价格为70至78美元。若按价格区间上限定价，并计入260亿美元的私募配售，此次IPO将筹资904亿美元，超过SpaceX创纪…"
