    "content": "11月18日，“深圳人全妆出街迎APEC”登上热搜。作为今年APEC东道主城市，深圳这几天的氛围热烈，市民用换新装、做发型、化全妆等方式来迎接这场盛会。就连代表着广东人松弛气质的“省鞋”人字拖，也被收了起来，大家纷纷拿出压箱底的西装、皮鞋，以十足的精气神迎接各国来宾。 深圳市民的发帖内容。图片来源：社交媒体截图 有深圳市民这么说，“要是街头采访到我的话，这可是全世界都能看到我。”这就是深圳人的“东道主的自我修养”。这看似只是穿衣打扮上的细节，其实从中可以窥见这座城市的精神气质。 深圳网友在网络平台上讨论留言。图片来…"
