    "content": "日本首相高市早苗星期三（11月18日）下午飞抵深圳，出席亚太经合组织（APEC）领导人非正式会议。前往机场迎接她的是已退休的前中国驻希腊大使章启月。 据香港《明报》报道，电视画面显示，章启月在机场迎接高市。相比之下，此次出席APEC会议的不少领导人，由广东省人大常委会主任黄楚平、广东省政协主席林克庆接机，也即由现任正部级干部迎接。 报道称，中方安排已退休的正局级官员迎接高市，现场也没有手持花束的学生欢迎队伍，接待规格“超低”。 报道也转述日本TBS电视台称，中方在机场欢迎高市的仪式规模不及参会的其他国家领导人。 公…"
