    "content": "新华社武汉11月18日电（记者熊翔鹤、田中全）提起秦朝，很多人印象里大多是律令严苛、征伐一统。湖北省云梦县新出土的一批简牍，却记录了当时基层治理的细节与普通人的生活点滴。通过这些沉睡千年的简牍，我们得以窥见远比史书所载更丰富、更鲜活的古代社会。 11月18日，国家文物局举行“考古中国”重大项目重要进展工作会，发布了4项长江文明溯源最新考古成果。其中，湖北云梦老虎墩墓地出土一批简牍及漆木器，这是继云梦睡虎地秦简、郑家湖木觚之后，云梦再次出土的大规模珍贵简牍，其文字材料为研究秦汉大一统王朝历史进程以及基层社会治理模式提…"
