    "description": "Glassdoor和Indeed的一份最新报告显示，美国越来越多地区的职位空缺开始增长，显示长期令求职者受挫的低招聘环境可能在明年出现转机。9月下旬美国近一半都会区的职位发布数量高于上年同期，占比为2022年以来最高。年初时，这一比例仅为约十分之一。在人口至少10万的385个都会区中，有299个地区的职位发布数量已经超过疫情前水平。（界面）",
