    "content": "新华社重庆11月18日电（记者赵佳乐）18日，2026现代服务业高质量发展大会在重庆举行。大会以“四化提质向新，品牌赋能强国”为主题，来自全国各地的企业代表、专家学者等共话现代服务业高质量发展前景以及服务品牌培育之道。 这是11月18日拍摄的2026现代服务业高质量发展大会现场。 新华社记者 王全超 摄 重庆市委常委、市政府常务副市长刘尚进介绍，近年来重庆高质量谋划推动服务业发展，着力构建以9大优势生产性服务业、6大特色生活性服务业、11张服务业发展“金名片”为主要内容的“9611”现代服务业体系，全市服务业发展环…"
