    "content": "韩国男子音乐组合BIGBANG星期二（11月17日）结束在香港举行的四场演唱会，累计吸引逾15万名观众入场，创下韩国歌手在香港举办演唱会的最多入场人数纪录。 综合香港《明报》和星岛头条网报道，BIGBANG香港站四场演唱会在启德主场馆举行，并于星期二晚落幕。香港成为BIGBANG此次世界巡回演唱会中演出场次最多的城市，同时创下启德体育园开幕以来，韩国艺人在单次演出期间举办最多场次的演唱会纪录。 演唱会期间，启德体育园及周边商户也迎来消费人潮，部分餐饮商户的营业额较平日增加约三成。 启德体育园行政总裁金民豪说，BIG…"
