    "description": "新华社北京11月18日电（记者冀泽）今冬首批台湾地区渔产品输入北京开箱仪式于18日举行，首批5000斤台湾午仔鱼在京深海鲜市场开箱销售。这是台湾渔产品输入大陆仪式10月23日在厦门举办后，首农食品集团所属北京水产集团与台湾高雄渔业企业的首次合作。 参加开箱仪式的北京台资企业协会副会长兼秘书长施心木表示，台湾渔业是广大台湾渔民重要生计来源，两岸的渔业合作串联起两岸渔民生计与百姓餐桌。北京市场广阔，是两岸农渔产品对接、台湾农渔产品展示和市场…",
    "content": "新华社北京11月18日电（记者冀泽）今冬首批台湾地区渔产品输入北京开箱仪式于18日举行，首批5000斤台湾午仔鱼在京深海鲜市场开箱销售。这是台湾渔产品输入大陆仪式10月23日在厦门举办后，首农食品集团所属北京水产集团与台湾高雄渔业企业的首次合作。 参加开箱仪式的北京台资企业协会副会长兼秘书长施心木表示，台湾渔业是广大台湾渔民重要生计来源，两岸的渔业合作串联起两岸渔民生计与百姓餐桌。北京市场广阔，是两岸农渔产品对接、台湾农渔产品展示和市场推广的重要窗口。此次合作将惠台政策落实到两岸渔产品产销合作上，是“两岸一家亲”的…"
