    "description": "位于广东深圳的盐田港是中国进出口贸易的重要门户，每周近百条航线通达世界各地。 作为全球最大单体集装箱码头之一，盐田港目前已经布局39条海铁联运线路、39个内陆港、18条大湾区驳船线路。未来，盐田港将加快开辟更多APEC成员经济体航线，进一步拓展友好港口网络，为互联互通的亚太供应链持续注入强劲动力。 记者：霍思颖、李思佳、毛思倩 新华社音视频部制作",
    "content": "位于广东深圳的盐田港是中国进出口贸易的重要门户，每周近百条航线通达世界各地。 作为全球最大单体集装箱码头之一，盐田港目前已经布局39条海铁联运线路、39个内陆港、18条大湾区驳船线路。未来，盐田港将加快开辟更多APEC成员经济体航线，进一步拓展友好港口网络，为互联互通的亚太供应链持续注入强劲动力。 记者：霍思颖、李思佳、毛思倩 新华社音视频部制作"
