    "content": "新华社北京11月18日电 原中央纪委驻人力资源和社会保障部纪检组组长、人力资源和社会保障部原党组成员袁彦鹏同志，因病于2026年10月26日在北京逝世，享年74岁。 袁彦鹏同志逝世后，中央有关领导同志以不同方式表示哀悼并向其亲属表示慰问。 袁彦鹏，1952年4月生，河北宁晋人。1970年12月参加工作，1973年8月加入中国共产党。1988年至1998年先后任人事部离休退休司退休处处长，养老保险处处长、副司长，社会保险与离退休管理司副司长、司长等。1998年至2007年先后任劳动和社会保障部办公厅副主任、人事教育司…"
