    "description": "泰国曼谷金山寺（Wat Saket）举行「红布包塔」法会。11月17日，曼谷金山寺举行一年一度的「红布包塔」祈福仪式，当地佛教信徒会将自己和家人的名字写在一块巨型红布上，然后将红布包裹在金山塔上以祈愿平安顺遂。泰国财政部数据显示2026年第三季度 GDP 同比增长2.9%，较上季度加快0.5个百分点，主要受到电子产品出口和私人投资增长推动，预计全年 GDP 增长率将达到2.5%。摄影师：Rungroj Yongrit",
    "content": "泰国曼谷金山寺（Wat Saket）举行「红布包塔」法会。11月17日，曼谷金山寺举行一年一度的「红布包塔」祈福仪式，当地佛教信徒会将自己和家人的名字写在一块巨型红布上，然后将红布包裹在金山塔上以祈愿平安顺遂。泰国财政部数据显示2026年第三季度 GDP 同比增长2.9%，较上季度加快0.5个百分点，主要受到电子产品出口和私人投资增长推动，预计全年 GDP 增长率将达到2.5%。摄影师：Rungroj Yongrit"
