    "description": "越共中央总书记、国家主席苏林18日在2026年亚太经合组织（APEC）工商领导人峰会上说，过去几十年来，不论是深圳自身、还是整个中国所取得的跨越式的发展成就，清晰地证明了坚持改革开放和创新发展的正确性，同时表明各经济体携手合作对共促繁荣的重要意义。 2026年APEC工商领导人峰会17日至18日在深圳前海国际会议中心举行。（视频：王沛、孙一、夏原一）",
    "content": "越共中央总书记、国家主席苏林18日在2026年亚太经合组织（APEC）工商领导人峰会上说，过去几十年来，不论是深圳自身、还是整个中国所取得的跨越式的发展成就，清晰地证明了坚持改革开放和创新发展的正确性，同时表明各经济体携手合作对共促繁荣的重要意义。 2026年APEC工商领导人峰会17日至18日在深圳前海国际会议中心举行。（视频：王沛、孙一、夏原一）"
