    "title": "聚焦APEC丨加拿大总理卡尼：“开放、创新、合作”对亚太发展至关重要",
    "link": "http://www.news.cn/20261118/fad68fb617a9419aae897c376fa3bc69/c.html",
    "pub_date": "2026-11-18 18:18:57",
