    "description": "新华社深圳11月18日电（记者金晶）加拿大总理卡尼18日在深圳出席亚太经合组织工商领导人峰会时表示，在当前国际局势下，“开放、创新、合作”对于促进整个亚太地区繁荣发展有着重要意义。 卡尼在峰会上致辞说，亚太各经济体应当加强经贸、金融等领域合作，并且持续推动创新，特别是在推动清洁能源经济发展方面。中国在风能、太阳能和储能等领域处于全球领先地位，为推动清洁能源领域合作提供了巨大可能。 卡尼说，今年年初，加中两国确立新型战略伙伴关系。双方将致…",
    "content": "新华社深圳11月18日电（记者金晶）加拿大总理卡尼18日在深圳出席亚太经合组织工商领导人峰会时表示，在当前国际局势下，“开放、创新、合作”对于促进整个亚太地区繁荣发展有着重要意义。 卡尼在峰会上致辞说，亚太各经济体应当加强经贸、金融等领域合作，并且持续推动创新，特别是在推动清洁能源经济发展方面。中国在风能、太阳能和储能等领域处于全球领先地位，为推动清洁能源领域合作提供了巨大可能。 卡尼说，今年年初，加中两国确立新型战略伙伴关系。双方将致力于增进互信，在经贸、能源、粮食安全、金融服务和人文交流等领域加强合作。 卡尼表…"
