    "description": "韩国总统李在明18日在2026年亚太经合组织（APEC）工商领导人峰会上说，不能在日益高筑的贸易壁垒面前停止开放，要将人工智能革命成果扩大至惠及所有人的创新，并为构建稳定的产业基础和供应链加强合作。最紧要的任务是通过扩大APEC区域内贸易和投资，拓展企业新的增长机会。 2026年APEC工商领导人峰会17日至18日在深圳前海国际会议中心举行。（视频：杨依然、周啸天、陆爱华）",
    "content": "韩国总统李在明18日在2026年亚太经合组织（APEC）工商领导人峰会上说，不能在日益高筑的贸易壁垒面前停止开放，要将人工智能革命成果扩大至惠及所有人的创新，并为构建稳定的产业基础和供应链加强合作。最紧要的任务是通过扩大APEC区域内贸易和投资，拓展企业新的增长机会。 2026年APEC工商领导人峰会17日至18日在深圳前海国际会议中心举行。（视频：杨依然、周啸天、陆爱华）"
