    "description": "新华社福州11月18日电（记者周义）记者从福州市水利局、福清市不动产登记和交易中心了解到，日前，福建省首宗亿元取水权不动产抵押登记在福州福清落地。福清市水投发展集团有限公司凭借4份取水权不动产抵押登记证明，获得4家金融机构合计2.13亿元综合授信。其中，福清市建新水库拿到银行1亿元授信额度，这意味着一库清水成为了可以用来贷款的资产。 据了解，此次授信的特殊之处在于抵押物不再是土地、厂房等传统不动产，而是取水权本身。过去，企业持有的取水许…",
    "content": "新华社福州11月18日电（记者周义）记者从福州市水利局、福清市不动产登记和交易中心了解到，日前，福建省首宗亿元取水权不动产抵押登记在福州福清落地。福清市水投发展集团有限公司凭借4份取水权不动产抵押登记证明，获得4家金融机构合计2.13亿元综合授信。其中，福清市建新水库拿到银行1亿元授信额度，这意味着一库清水成为了可以用来贷款的资产。 据了解，此次授信的特殊之处在于抵押物不再是土地、厂房等传统不动产，而是取水权本身。过去，企业持有的取水许可证仅是行政层面的许可凭证，不具备抵押融资功能，长期面临“确权难、流转难、抵押难…"
